import React, { useState, useMemo } from 'react';
import { Search, BookMarked, ChevronDown, ChevronUp } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface Term {
  term: string;
  meaning: string;
  source: string;
  example: string;
  category: string;
}

const TERMS: Term[] = [
  // NLC & Title
  { term: 'Indefeasibility of Title', category: 'NLC Principles', meaning: 'The principle that a registered proprietor\'s title cannot be defeated or challenged, once registered, except on grounds specified in the National Land Code.', source: 'Section 340, National Land Code 1965 (NLC)', example: 'Once Ah Kow registers his name on the title after purchasing the land, he holds an indefeasible title that cannot be set aside except if he obtained it through fraud or forgery.' },
  { term: 'Deferred Indefeasibility', category: 'NLC Principles', meaning: 'The rule that a person who acquires title through a void instrument does not obtain indefeasible title immediately; only a subsequent bona fide purchaser for value obtains indefeasibility.', source: 'Section 340(2) & (3) NLC; Tan Ying Hong v Tan Sian San [2010]', example: 'Where a forger A transfers land to B (immediate purchaser), B\'s title is defeasible. Only when B sells to C (a bona fide purchaser for value without notice of fraud) does indefeasibility attach to C\'s title.' },
  { term: 'Torrens System', category: 'NLC Principles', meaning: 'The system of land registration where the register is the mirror of title and registration confers ownership, as opposed to the old deeds system.', source: 'National Land Code 1965; Introduced in Malaysia via Federated Malay States (Cadastral Survey) Act 1915', example: 'Unlike England\'s old deed system, Malaysia\'s Torrens system means the buyer checks the title register at PTG — if the seller\'s name is there and the title is clean, the buyer can proceed safely.' },
  { term: 'Issue Document of Title (IDT)', category: 'NLC Principles', meaning: 'The physical copy of the title held by the registered proprietor, as opposed to the register kept at the Land Registry.', source: 'Section 92 NLC', example: 'The bank holds the original IDT as security when a property is charged. On full repayment of the loan, the IDT is returned to the owner.' },
  { term: 'Qualified Title', category: 'NLC Principles', meaning: 'A title issued before the survey of the land has been completed and approved; it is subject to amendment upon completion of the survey.', source: 'Section 168 NLC', example: 'Many new housing estates in Sabah and Sarawak have qualified titles. The title will be converted to final title (Geran) once the cadastral survey is finalised.' },
  { term: 'Final Title (Geran)', category: 'NLC Principles', meaning: 'A title that has been issued after the survey has been completed and gazetted; it is permanent and not subject to further cadastral amendment.', source: 'Section 169 NLC', example: 'A freehold house in a mature residential area in Petaling Jaya typically has a Final Title (Geran), confirming the exact boundaries of the land.' },
  { term: 'Restriction in Interest', category: 'NLC Principles', meaning: 'A condition endorsed on a title restricting the owner\'s ability to deal with the land (e.g. sell, transfer, charge) without prior consent of a specified authority.', source: 'Section 119 NLC', example: 'A Malay Reserve Land title may carry a restriction that it can only be transferred to a Malay person. Before selling, the vendor must get state authority consent to lift or waive this restriction.' },
  { term: 'Express Condition', category: 'NLC Principles', meaning: 'A specific condition imposed on the title at the time of alienation by the State Authority relating to the use of the land.', source: 'Section 120 NLC', example: 'A title with an express condition "for residential purposes only" cannot be used to operate a factory without first applying to the State Authority to vary the condition.' },
  { term: 'Implied Condition', category: 'NLC Principles', meaning: 'A statutory condition deemed to be attached to every alienated land under the NLC regardless of whether it is expressly stated on the title.', source: 'Section 114–115 NLC', example: 'Every piece of alienated land is impliedly subject to the condition that it must not be used in a manner repugnant to its category of land use without prior permission.' },
  { term: 'Alienation of Land', category: 'NLC Principles', meaning: 'The grant of State Land by the State Authority to an individual or body, creating a new registered proprietorship.', source: 'Section 76–79 NLC', example: 'When a company applies for land and the State Authority approves and issues a title, this is an alienation. It is the process by which State land becomes private land.' },

  // Conveyancing Process
  { term: 'Memorandum of Transfer (MOT)', category: 'Transfer & Registration', meaning: 'The prescribed statutory instrument (Form 14A under NLC) used to transfer ownership of land from one person to another upon presentation and registration at the Land Office.', source: 'Section 215 & Form 14A, National Land Code 1965', example: 'After the SPA completion, the purchaser\'s solicitor prepares the Form 14A (MOT), has it executed by both parties, stamped at LHDN, and presents it to the Land Office for registration.' },
  { term: 'Presentment', category: 'Transfer & Registration', meaning: 'The act of lodging an instrument (e.g. MOT, Charge) at the Land Registry or Land Office for registration.', source: 'Section 298 NLC', example: 'The solicitor presents the original IDT, executed Form 14A, and relevant fees at the Pejabat Tanah window. The officer time-stamps it and issues a receipt of presentment.' },
  { term: 'Encumbrance', category: 'Transfer & Registration', meaning: 'A burden or liability attached to land, such as a charge, lien, easement, or caveat, which affects the owner\'s free use or transfer of the land.', source: 'Section 5 NLC (definition)', example: 'A bank charge registered on the title is an encumbrance. The vendor must redeem this charge before or upon completion so the purchaser receives a clean title.' },
  { term: 'Strata Title', category: 'Transfer & Registration', meaning: 'An individual title issued for a unit within a subdivided building (e.g. condominium, apartment, flat), governed by the Strata Titles Act 1985.', source: 'Strata Titles Act 1985; Strata Management Act 2013', example: 'A condominium unit owner holds a Strata Title, which describes the parcel and its share value (unit entitlement) within the entire building.' },
  { term: 'Lot Number / Geran Number', category: 'Transfer & Registration', meaning: 'The unique identifier assigned to a piece of land in the land register. The Geran number appears on the Individual Title.', source: 'National Land Code 1965', example: 'A title may read "Geran 12345, Lot 678, Mukim Ampang, Daerah Hulu Langat, Selangor." This uniquely identifies the plot in the state land register.' },
  { term: 'Mukim / Pekan / Bandar', category: 'Transfer & Registration', meaning: 'Administrative subdivisions used to categorise land in the Malaysian land registry. Mukim is a sub-district; Pekan is a town; Bandar is a municipality.', source: 'National Land Code 1965', example: 'A property in Petaling Jaya may be in "Mukim Petaling, Daerah Petaling, Selangor." This information is required on all land instruments.' },
  { term: 'Ad Valorem Stamp Duty', category: 'Stamp Duty', meaning: 'Stamp duty calculated as a percentage of the transaction value (purchase price or loan amount), as opposed to a fixed sum.', source: 'Stamp Act 1949; First Schedule', example: 'The stamp duty on a RM700,000 SPA is: 1% on RM100k (RM1,000) + 2% on RM400k (RM8,000) + 3% on RM200k (RM6,000) = RM15,000.' },
  { term: 'Adjudication (Stamp Duty)', category: 'Stamp Duty', meaning: 'The process by which LHDN assesses the correct stamp duty payable on an instrument and endorses it accordingly.', source: 'Section 36–39 Stamp Act 1949', example: 'When the property price in the SPA is disputed or unclear, the solicitor sends the instrument to LHDN for adjudication. LHDN stamps the document after assessing the correct duty.' },

  // Financing
  { term: 'Charge', category: 'Financing', meaning: 'A registered security interest over land granted by the landowner (chargor) to a financier (chargee) to secure a loan. Under Malaysian law, it is a statutory creation under the NLC, not a common law mortgage.', source: 'Section 241 NLC', example: 'When you take a bank loan to buy a house, the bank registers a charge (Form 16A) against your title. You remain the registered proprietor but the bank has a security interest until the loan is repaid.' },
  { term: 'Chargor & Chargee', category: 'Financing', meaning: 'The Chargor is the landowner who creates the charge as security; the Chargee is the financier (bank) who holds the charge.', source: 'Section 241 NLC', example: 'Buyer Ali is the Chargor; Maybank is the Chargee. Ali grants the charge to Maybank as security for his housing loan.' },
  { term: 'Discharge of Charge', category: 'Financing', meaning: 'The release of a registered charge over land upon full repayment of the secured debt, effected by lodging Form 16N at the Land Office.', source: 'Section 278 NLC; Form 16N', example: 'After fully repaying his 30-year mortgage, Ali\'s solicitor lodges Form 16N with the original IDT at the Land Office to remove the bank\'s charge from his title.' },
  { term: 'Deed of Assignment (DOA)', category: 'Financing', meaning: 'A document used to assign a borrower\'s rights and interest in a property (typically under a SPA for land without individual title yet) to a bank as security for a loan.', source: 'Common law; used in Malaysia before individual title is issued', example: 'For a developer unit where the strata title has not yet been issued, the purchaser-borrower executes a Deed of Assignment assigning his rights under the SPA to the bank as security.' },
  { term: 'Loan Agreement Cum Assignment (LACA)', category: 'Financing', meaning: 'A combined financing document containing both the loan agreement and the deed of assignment of the SPA rights, used where no individual title exists.', source: 'Common law and practice; not a statutory form', example: 'Maybank prepares a LACA for a buyer of a new condominium (no strata title yet). Once the strata title is issued, a charge (Form 16A) will be registered in substitution of the LACA.' },
  { term: 'Redemption Sum', category: 'Financing', meaning: 'The total amount outstanding on a housing loan (principal + accrued interest + fees) that must be paid to the bank to fully discharge the charge.', source: 'Loan agreement; NLC', example: 'Ali wants to sell his house. His bank confirms the redemption sum is RM450,000. This amount is paid from the sale proceeds to the bank on completion, and the bank then discharges the charge.' },
  { term: 'Undertaking (Legal)', category: 'Financing', meaning: 'A binding promise by a solicitor to do or refrain from doing a specific act. In conveyancing, often the vendor\'s solicitor undertakes to discharge an existing charge upon receipt of the sale proceeds.', source: 'Bar Council practice rules; contract law', example: 'The vendor\'s bank gives an undertaking to the purchaser\'s bank to discharge the charge upon receipt of the redemption sum, enabling the transaction to complete on the same day.' },

  // Caveats
  { term: 'Private Caveat', category: 'Caveats', meaning: 'A statutory entry on the title registered by a person who claims an interest in land (e.g. under a SPA or equitable interest), preventing any further dealings without notice to the caveator.', source: 'Section 323 NLC; Form 19B', example: 'A purchaser who has signed a SPA but the transfer has not yet been registered may lodge a private caveat to protect his equitable interest and prevent the vendor from selling to a third party.' },
  { term: 'Registrar\'s Caveat', category: 'Caveats', meaning: 'A caveat lodged by the Land Registrar to protect the interests of a person under disability (minor, lunatic) or at the direction of a court order.', source: 'Section 319 NLC', example: 'The Land Registrar enters a Registrar\'s Caveat on a deceased person\'s land to freeze dealings until the estate is administered through the proper legal channels.' },
  { term: 'Lien-Holder\'s Caveat', category: 'Caveats', meaning: 'A caveat entered by a lien-holder (a person who has deposited the issue document of title as security without executing a formal charge) to protect their interest in the land.', source: 'Section 330 NLC', example: 'A moneylender who holds the original land title as security deposits the IDT and enters a lien-holder\'s caveat. This prevents the owner from registering a transfer or charge without the lien-holder\'s knowledge.' },
  { term: 'Withdrawal of Caveat', category: 'Caveats', meaning: 'The removal of a caveat from the register, either voluntarily by the caveator (Form 19G) or by court order where the caveator fails to justify the caveat.', source: 'Section 327 NLC; Form 19G', example: 'After the SPA is completed and the MOT registered, the purchaser withdraws the private caveat he lodged earlier, as his interest is now fully protected by registration of the title.' },

  // HDA & Developer
  { term: 'Housing Development Act (HDA)', category: 'HDA & Developer', meaning: 'The Housing Development (Control and Licensing) Act 1966, the principal statute regulating housing developers in Peninsular Malaysia and Labuan, governing matters like licensing, statutory SPA forms, and deposit protections.', source: 'Housing Development (Control and Licensing) Act 1966', example: 'A developer who sells a residential property must be licensed under the HDA, use the statutory SPA schedules (G, H, I, or J), and cannot charge a booking fee exceeding RM500.' },
  { term: 'Liquidated Ascertained Damages (LAD)', category: 'HDA & Developer', meaning: 'A pre-agreed sum of damages payable for a specific breach (typically late delivery of vacant possession) without needing to prove actual loss.', source: 'Housing Development (Control and Licensing) Regulations 1989; Schedule G & H SPA', example: 'If a developer fails to deliver vacant possession by the agreed date, it must pay LAD calculated at 10% p.a. on the purchase price for each day of delay, without the buyer needing to prove financial loss.' },
  { term: 'Vacant Possession (VP)', category: 'HDA & Developer', meaning: 'Delivery of the property to the purchaser free of any occupants and in a condition fit for occupation, which triggers the start of the defect liability period.', source: 'Housing Development (Control and Licensing) Regulations 1989', example: 'On the VP date, the developer hands over the keys and utilities are connected. The purchaser inspects the unit and the 24-month defect liability period begins.' },
  { term: 'Defect Liability Period (DLP)', category: 'HDA & Developer', meaning: 'The period (typically 24 months) after delivery of vacant possession during which the developer is obliged to repair any defects in workmanship or materials at no cost to the purchaser.', source: 'Schedule G & H SPA under Housing Development (Control and Licensing) Regulations 1989', example: 'Six months after moving in, the purchaser notices cracks in the wall. As the DLP is still running, she submits a defect report and the developer must repair it within 30 days at no charge.' },
  { term: 'Certificate of Completion and Compliance (CCC)', category: 'HDA & Developer', meaning: 'The certificate issued by the Principal Submitting Person (architect or engineer) confirming that a building has been completed and complies with approved plans and building by-laws, replacing the old Certificate of Fitness (CF).', source: 'Street, Drainage and Building Act 1974 (amended 2007)', example: 'The developer can only deliver vacant possession after the CCC has been issued for the building. Without a CCC, the building is not certified safe for occupation.' },
  { term: 'Management Corporation (MC)', category: 'Strata & MC', meaning: 'A statutory body comprising all parcel owners in a strata development, responsible for the management and maintenance of common property and the building.', source: 'Strata Management Act 2013; Strata Titles Act 1985', example: 'Once the strata titles are issued and a certain number are sold, the Management Corporation is automatically constituted. Every unit owner is automatically a member and liable to pay monthly maintenance charges.' },
  { term: 'Joint Management Body (JMB)', category: 'Strata & MC', meaning: 'A transitional management body comprising the developer and purchasers that manages a strata property from the date of VP until the Management Corporation is formed.', source: 'Strata Management Act 2013 (Section 17)', example: 'A new condominium delivered in 2023 has a JMB managing maintenance fees and repairs. Once the strata titles are issued, the JMB will be dissolved and the MC will take over.' },
  { term: 'Parcel', category: 'Strata & MC', meaning: 'An individual unit in a strata development — equivalent to a "lot" for landed property. Each parcel has its own strata title.', source: 'Strata Titles Act 1985; Strata Management Act 2013', example: 'Unit 15-3 of Condominium Bukit Indah is a "parcel." The owner holds a strata title for this parcel and shares ownership of common areas with all other parcel owners.' },
  { term: 'Share Unit / Unit Entitlement', category: 'Strata & MC', meaning: 'A numerical allocation assigned to each parcel representing its proportional interest in the common property and its liability to pay maintenance charges.', source: 'Strata Titles Act 1985', example: 'A 1,200 sq ft unit has a share unit of 12, while a 800 sq ft unit has 8. Maintenance charges and voting rights at MC meetings are proportional to share units.' },

  // RPGT & Tax
  { term: 'Real Property Gains Tax (RPGT)', category: 'Taxation', meaning: 'A tax on the gains made from the disposal (sale) of real property or shares in a Real Property Company, chargeable on the disposer (vendor).', source: 'Real Property Gains Tax Act 1976 (RPGT Act)', example: 'Ali bought a house for RM400,000 in 2019 and sells it in 2023 for RM550,000. He has a gain of RM150,000. Being a Malaysian citizen disposing within 4 years, he is taxed at 15% RPGT = RM22,500.' },
  { term: 'CKHT 1A Form', category: 'Taxation', meaning: 'The RPGT return form submitted by the disposer (vendor/seller) to LHDN within 60 days of the date of disposal (SPA signing).', source: 'Section 13 Real Property Gains Tax Act 1976', example: 'The vendor\'s solicitor submits Form CKHT 1A to the local LHDN branch within 60 days of the SPA date to declare the disposal and compute RPGT.' },
  { term: 'CKHT 2A Form', category: 'Taxation', meaning: 'The acquisition return submitted by the purchaser (acquirer) to LHDN within 60 days of the SPA date.', source: 'Section 14 Real Property Gains Tax Act 1976', example: 'The purchaser\'s solicitor submits Form CKHT 2A to LHDN declaring the acquisition. The purchaser must also withhold 3% of the purchase price (CKHT retention) to remit to LHDN.' },
  { term: 'CKHT 3% Retention', category: 'Taxation', meaning: 'The requirement for the purchaser to retain 3% of the purchase price and remit it to LHDN as a withholding tax payment on account of the vendor\'s potential RPGT liability.', source: 'Section 21B Real Property Gains Tax Act 1976', example: 'The purchaser retains RM15,000 (3% of RM500,000 purchase price) from the balance purchase price and pays it directly to LHDN. If the vendor\'s RPGT is less, the excess is refunded.' },
  { term: 'Solicitors Remuneration Order (SRO)', category: 'Fees & Costs', meaning: 'The subsidiary legislation prescribing the scale of professional fees chargeable by solicitors for conveyancing and other legal services in Malaysia.', source: 'Solicitors Remuneration Order 2023 (replacing 2005 Order)', example: 'Under SRO 2023, legal fees for a RM500,000 SPA are 1% = RM5,000. For a RM1,000,000 property: 1% on first RM500k + 0.8% on next RM500k = RM5,000 + RM4,000 = RM9,000.' },

  // Agreements & Instruments
  { term: 'Sale and Purchase Agreement (SPA)', category: 'Agreements', meaning: 'The principal binding contract between the vendor and purchaser setting out all terms and conditions for the sale and purchase of the property.', source: 'Contracts Act 1950; Specific Relief Act 1950; NLC', example: 'The SPA for a sub-sale property records the parties\' details, the property description, purchase price, payment terms, completion date, and all conditions of sale.' },
  { term: 'Option to Purchase (OTP)', category: 'Agreements', meaning: 'A preliminary agreement granting the potential buyer the exclusive right (option) to purchase a property at a fixed price within a specified period upon payment of an option fee.', source: 'Contracts Act 1950; equity', example: 'The vendor grants the purchaser a 14-day OTP upon payment of a 1% option fee. If the purchaser exercises the option by signing the SPA and paying the remaining 9% deposit within 14 days, the vendor cannot sell to anyone else.' },
  { term: 'Specific Performance', category: 'Agreements', meaning: 'An equitable remedy ordered by a court requiring a party in breach of a contract to perform their obligations under the contract, rather than paying damages.', source: 'Section 11 Specific Relief Act 1950; Macon Works & Trading v Phang Hon Yin [1976]', example: 'The vendor refuses to complete the sale after signing the SPA. The purchaser sues and obtains an order for specific performance, forcing the vendor to proceed with the transfer of the property.' },
  { term: 'Power of Attorney (PA)', category: 'Agreements', meaning: 'A legal instrument authorising one person (the attorney or donee) to act on behalf of another (the donor/principal) in legal or financial matters.', source: 'Powers of Attorney Act 1949; NLC', example: 'An elderly vendor who is hospitalised grants a Power of Attorney to his son to sign the SPA and all related documents on his behalf.' },
  { term: 'Earnest Deposit', category: 'Agreements', meaning: 'A sum of money (typically 2–3% of the purchase price) paid by the purchaser to demonstrate good faith when making an offer to purchase property, often held by an estate agent or solicitor as stakeholder.', source: 'Contracts Act 1950; estate agency practice', example: 'The purchaser pays RM10,000 as earnest deposit (2% of RM500,000) to the estate agent. If the purchaser withdraws, the deposit is forfeited. If the vendor withdraws, the vendor must return double the deposit.' },
  { term: 'Stakeholder', category: 'Agreements', meaning: 'A neutral party (solicitor or licensed real estate agent) who holds monies or documents on behalf of both parties to a transaction pending completion of the agreed conditions.', source: 'Conveyancing practice; Solicitors Accounts Rules', example: 'The purchaser\'s solicitor holds the 10% deposit as stakeholder. The money cannot be released to the vendor until the SPA is completed and the title is transferred.' },
  { term: 'Conveyance', category: 'General Conveyancing', meaning: 'The legal process of transferring ownership of property from one person to another, including all steps from the agreement to the registration of the transfer.', source: 'Common law; NLC', example: 'The solicitor handles the conveyance — from reviewing the SPA, conducting searches, preparing the MOT, to lodging it at the Land Office for registration in the purchaser\'s name.' },
  { term: 'Requisition on Title', category: 'General Conveyancing', meaning: 'Queries raised by the purchaser\'s solicitor to the vendor\'s solicitor arising from the title search, requesting clarification or rectification of any issues found on or relating to the title.', source: 'Conveyancing practice; NLC', example: 'The purchaser\'s solicitor discovers a private caveat on the title and raises a requisition requiring the vendor to remove it within a specified time before completion.' },
  { term: 'Quit Rent (Cukai Tanah)', category: 'General Conveyancing', meaning: 'An annual land tax payable by the registered proprietor to the State Government, assessed on the land area and category of land use.', source: 'National Land Code 1965; Land Ordinances (Sabah/Sarawak)', example: 'Before completion, the vendor provides a receipt showing quit rent is paid up to date. The purchaser\'s solicitor apportions any outstanding quit rent between the parties.' },
  { term: 'Assessment (Cukai Taksiran)', category: 'General Conveyancing', meaning: 'A local government tax imposed on the annual value of property, payable to the local authority (Majlis Bandaraya / Perbandaran / Daerah) bi-annually.', source: 'Local Government Act 1976', example: 'The vendor provides the last paid assessment receipt. Upon completion, the solicitor sends a notice to the local authority to update the assessment billing to the new owner\'s name.' },
  { term: 'Priority Search', category: 'General Conveyancing', meaning: 'An urgent official search at the Land Registry to check the state of a title immediately before presentation of an instrument, to confirm there are no intervening registrations or caveats since the last search.', source: 'NLC conveyancing practice', example: 'On the day of completion, the solicitor conducts a priority search at 9am to confirm the title is clean before lodging the MOT and charge at 2pm.' },
  { term: 'Apportionment', category: 'General Conveyancing', meaning: 'The division of outgoings (quit rent, assessment, maintenance fees) between vendor and purchaser on a pro-rata basis as at the completion date.', source: 'Conveyancing practice; SPA terms', example: 'If assessment for the year is RM1,200 and the property completes on 1 July, the vendor pays 6/12 (RM600) and the purchaser pays 6/12 (RM600). The solicitor adjusts this in the completion account.' },
  { term: 'Sub-Sale', category: 'General Conveyancing', meaning: 'The sale of property by a purchaser (who has not yet received the title) to a third party, typically where the property was originally purchased from a developer.', source: 'Conveyancing practice; NLC; Housing Development Act', example: 'Mary bought a condominium from a developer in 2018 (no strata title yet). In 2023, she sells it to John before receiving the strata title. This is a sub-sale transaction.' },
  { term: 'Bumiputera Lot', category: 'General Conveyancing', meaning: 'A property allocated exclusively for purchase by Bumiputera buyers under State or Federal Government policy, usually carrying a restriction against sale to non-Bumiputera without state consent.', source: 'State Land Enactments; Housing Development policies', example: 'A new housing project may have 30% units designated as Bumiputera lots. These units carry a restriction in interest on the title: they may only be sold to Bumiputera persons without state consent to release the restriction.' },
  { term: 'RPGT Exemption — Once in Lifetime', category: 'Taxation', meaning: 'A one-time exemption from RPGT available to Malaysian citizens on the disposal of one private residential property, regardless of the holding period.', source: 'Paragraph 2(1), Schedule 4, Real Property Gains Tax Act 1976', example: 'Ahmad sells his house at a gain after 2 years. Normally RPGT at 30% applies. However, as he has never used the exemption before, he elects the "once in a lifetime" exemption, making his RPGT liability nil.' },
  { term: 'Order for Sale', category: 'Foreclosure', meaning: 'A court order obtained by a chargee (bank) under Section 256 NLC or via High Court proceedings to sell the charged land at public auction when the chargor (borrower) defaults on the loan.', source: 'Section 256 NLC; Order 83 Rules of Court 2012', example: 'After Ali defaults on his mortgage for 6 months, Maybank files for an Order for Sale at the High Court. Once obtained, the property is auctioned to recover the outstanding loan amount.' },
  { term: 'Proclamation of Sale', category: 'Foreclosure', meaning: 'The public notice issued by the court or land administrator announcing the date, time, place, and conditions for the auction sale of a foreclosed property.', source: 'Order 83 Rules of Court 2012; NLC', example: 'The Proclamation of Sale is advertised in newspapers and posted on the court noticeboard 30 days before the auction. It details the property, reserve price, and conditions bidders must meet.' },
  { term: 'Vesting Order', category: 'Foreclosure', meaning: 'A court order directing the Land Registrar to register a successful auction purchaser as the new proprietor of foreclosed land, without the need for a conventional Form 14A (MOT).', source: 'Section 258 NLC; Order 83 Rules of Court 2012', example: 'After winning the court auction and paying the balance price, the purchaser\'s solicitor applies to court for a Vesting Order. On registration of the Vesting Order, the purchaser becomes the new registered proprietor.' },
  { term: 'Equity of Redemption', category: 'Foreclosure', meaning: 'The chargor\'s right to recover their charged land by paying all outstanding sums (principal + interest + costs) at any time before the completion of the foreclosure sale.', source: 'Equity; NLC s.256', example: 'Even after the bank has obtained an Order for Sale, the chargor may still redeem the property by paying the full outstanding debt before the auction is completed. This last-chance right is the equity of redemption.' },
  { term: 'Reserve Price', category: 'Foreclosure', meaning: 'The minimum price set by the court in the Proclamation of Sale below which the property cannot be sold at the mortgagee auction.', source: 'Order 83 Rules of Court 2012; court practice', example: 'A property with market value RM600,000 is given a reserve price of RM480,000 (80% of value) in the Proclamation of Sale. Bidders must open bidding at RM480,000 or above.' },

  // NLC Principles (Additional)
  { term: 'Mirror Principle', category: 'NLC Principles', meaning: 'A fundamental Torrens principle that the register is a "mirror" reflecting accurately and completely the current state of a registered title, including all interests and encumbrances.', source: 'Torrens system; National Land Code 1965', example: 'A purchaser conducting a title search at PTG should find all relevant information (owner\'s name, charges, caveats, conditions) clearly reflected on the register — it is the mirror of title.' },
  { term: 'Curtain Principle', category: 'NLC Principles', meaning: 'A Torrens principle that "draws a curtain" over the past dealings with land — a purchaser need only look at the current register and is not concerned with the history of earlier dealings.', source: 'Torrens system; NLC', example: 'A purchaser need not investigate how the current registered owner originally acquired the land, or trace all prior transactions. The register\'s curtain keeps that history behind it — only the current registered state matters.' },
  { term: 'Insurance Principle', category: 'NLC Principles', meaning: 'The Torrens principle that where a registered proprietor loses their land due to a defect in the system (e.g. administrative error), they are entitled to compensation from the State (assurance fund).', source: 'NLC s.340; Assurance Fund principles', example: 'If the Land Registrar makes an error leading to the registration of a fraudulent title that defeats the true owner, the true owner may claim compensation from the State\'s assurance fund — a form of "insurance" for Torrens system integrity.' },
  { term: 'Category of Land Use', category: 'NLC Principles', meaning: 'The classification of land under the NLC into one of three categories: (1) Agriculture, (2) Building, or (3) Industry, which determines the permitted uses of the land.', source: 'Section 52 NLC (Category of Land Use)', example: 'A factory cannot be built on land categorised as "Agriculture" without first applying to the State Authority to change the category to "Industry." Operating a factory on agricultural land breaches an implied condition.' },
  { term: 'Forfeiture of Land', category: 'NLC Principles', meaning: 'The State Authority\'s power to forfeit (reclaim) alienated land where the registered proprietor breaches an express or implied condition of the title.', source: 'Section 127–134 NLC', example: 'A landowner who uses his "agriculture" category land for operating an illegal quarry (a condition breach) may receive a "show cause" notice from the land office. If he cannot justify the breach, the State may forfeit the land.' },
  { term: 'State Land', category: 'NLC Principles', meaning: 'All land in a state that has not been alienated or otherwise disposed of by the State Authority — it remains the property of the State.', source: 'Section 40–45 NLC', example: 'A riverside area that has not been alienated to any private person remains State Land. Anyone wishing to use it must apply to the State for alienation or a temporary occupation licence (TOL).' },

  // Transfer & Registration (Additional)
  { term: 'Easement', category: 'Transfer & Registration', meaning: 'A right held by one landowner to use part of a neighbouring landowner\'s land for a specific purpose (e.g. a right of way over the neighbour\'s land to access a road).', source: 'Sections 281–287 NLC; common law', example: 'The owner of a land-locked plot has a right of way easement over the neighbouring plot to access the main road. The easement must be registered on both titles to be fully effective.' },
  { term: 'Covenant Running with Land', category: 'Transfer & Registration', meaning: 'A promise relating to land that binds not just the original parties but also their successors in title — typically where it is registered or noted on the title.', source: 'NLC; common law; equity', example: 'A developer imposes a restrictive covenant on a housing estate that no two-storey house shall be built. This covenant may run with the land and bind subsequent purchasers, keeping the estate uniform.' },
  { term: 'Caveat Emptor', category: 'Transfer & Registration', meaning: '"Let the buyer beware" — the common law principle that the purchaser takes property as found and must conduct their own due diligence, as the vendor has no obligation to disclose defects unless asked.', source: 'Common law principle (modified by HDA for housing developers)', example: 'In a sub-sale, the principle of caveat emptor applies — the purchaser must inspect the property and inquire about its condition. The vendor need not volunteer information about a leaking roof unless specifically asked.' },
  { term: 'Transmission', category: 'Transfer & Registration', meaning: 'The vesting of a registered proprietor\'s title in another person by operation of law (e.g. upon death or bankruptcy), as opposed to a voluntary transfer (Form 14A).', source: 'Section 345–349 NLC (Forms 14B, 14C, 14D)', example: 'When a sole registered proprietor dies, the title does not automatically vest in the next of kin. The administrator/executor must apply for a Transmission using Form 14B, which is the legal mechanism by which the title transfers by law.' },
  { term: 'Right of Survivorship', category: 'Transfer & Registration', meaning: 'The automatic vesting of the deceased joint tenant\'s share in the surviving joint tenant(s) upon death, without the need for probate or letters of administration.', source: 'Section 348 NLC; common law', example: 'Ali and Siti own a property as joint tenants. Ali dies. Siti automatically acquires Ali\'s full share by the right of survivorship — she files a Form 14D at the Land Office with the death certificate.' },
  { term: 'Tenancy in Common', category: 'Transfer & Registration', meaning: 'A form of co-ownership where each co-owner has a distinct fractional share in the land (e.g. 50:50 or 60:40), and upon death, the deceased\'s share passes to their estate (no right of survivorship).', source: 'NLC; common law', example: 'Ali and Siti own property as tenants in common in equal shares. If Ali dies, his 50% share goes to his beneficiaries under his will or intestacy — not automatically to Siti. This is unlike joint tenancy.' },
  { term: 'Joint Tenancy', category: 'Transfer & Registration', meaning: 'A form of co-ownership where all co-owners hold the land together as a whole, bound by the four unities (possession, interest, time, title). On death, the survivor automatically inherits.', source: 'Common law; NLC', example: 'A husband and wife register their matrimonial home as joint tenants. On the husband\'s death, the wife automatically becomes sole proprietor by the right of survivorship — no need for probate on the property.' },
  { term: 'Severance of Joint Tenancy', category: 'Transfer & Registration', meaning: 'The act of converting a joint tenancy to a tenancy in common, so that each party\'s share becomes separately alienable and passes under their will/estate on death.', source: 'Common law; NLC', example: 'Ali and Siti are joint tenants. Ali, wanting to leave his share to his children, serves written notice on Siti of his intention to sever the joint tenancy. From that point, they hold as tenants in common in equal shares.' },

  // Financing (Additional)
  { term: 'Mortgage Reducing Term Assurance (MRTA)', category: 'Financing', meaning: 'A single-premium life insurance policy (decreasing sum assured) that covers the outstanding housing loan balance in the event of the borrower\'s death or total permanent disability.', source: 'Insurance regulation; banking practice', example: 'A borrower takes a RM500,000 housing loan for 30 years and purchases MRTA. If the borrower dies in year 10, the MRTA policy pays out the then-outstanding loan balance directly to the bank, freeing the family of the mortgage debt.' },
  { term: 'Mortgage Level Term Assurance (MLTA)', category: 'Financing', meaning: 'A level-sum life insurance policy that pays out a fixed amount (equal to the original loan) upon death/disability, and may also accumulate cash value. Any surplus after settling the loan goes to the beneficiary.', source: 'Insurance regulation; banking practice', example: 'A borrower with RM500,000 MLTA who dies in year 10 (when the outstanding loan is RM350,000) triggers a RM500,000 payout. The bank gets RM350,000; the beneficiary gets the RM150,000 surplus.' },
  { term: 'Lock-in Period', category: 'Financing', meaning: 'A period specified in the loan agreement during which the borrower cannot fully redeem the loan without incurring an early termination penalty.', source: 'Loan agreement terms; Bank Negara Malaysia guidelines', example: 'A bank offers a 3-year lock-in period. If the borrower refinances in year 2, the bank charges a penalty of 2% of the outstanding loan balance as an early redemption fee.' },
  { term: 'Loan-to-Value Ratio (LTV)', category: 'Financing', meaning: 'The ratio of the loan amount to the appraised market value of the property, expressed as a percentage. It determines how much a bank will lend against a property.', source: 'Bank Negara Malaysia prudential guidelines', example: 'A property is valued at RM500,000. A bank offering 90% LTV will lend up to RM450,000. The borrower must fund the remaining RM50,000 from their own savings as the down payment.' },
  { term: 'Debt Service Ratio (DSR)', category: 'Financing', meaning: 'A measure of a borrower\'s ability to repay debt, calculated as total monthly debt obligations divided by gross monthly income. Banks use DSR to assess creditworthiness.', source: 'Bank Negara Malaysia guidelines; banking practice', example: 'Ahmad earns RM8,000/month. His existing car loan is RM1,200/month. His new housing loan instalment is RM2,000/month. His DSR = (RM1,200 + RM2,000) / RM8,000 = 40%. Most banks allow up to 70% DSR.' },
  { term: 'Bridging Finance', category: 'Financing', meaning: 'Short-term financing obtained by a developer to fund the construction of a housing project, repaid as purchasers\' progress payments are received. Also used by purchasers to bridge the gap between purchasing and selling another property.', source: 'Banking practice; Housing Development Act', example: 'A developer obtains RM20M bridging finance from a bank to build a housing project. As homes are sold and progress payments collected, the developer repays the bridging loan. Interest runs until full repayment.' },
  { term: 'End Finance', category: 'Financing', meaning: 'Long-term housing loan obtained by the purchaser from a bank to finance the purchase of property from a developer. It is disbursed progressively to the developer according to construction progress.', source: 'Banking practice; HDA Schedule G progressive payment schedule', example: 'A purchaser obtains RM400,000 end finance from Maybank. Maybank disburses to the developer progressively: 10% on land, 15% on piling, 30% on structure, etc. — following the SPA\'s progressive payment schedule.' },
  { term: 'Progressive Payment', category: 'Financing', meaning: 'A payment schedule for new developer property where the purchase price is paid in stages as the building reaches different stages of construction, rather than as a lump sum.', source: 'Housing Development (Control and Licensing) Regulations 1989 — Third Schedule', example: 'A purchaser\'s bank releases progressive payments according to the SPA schedule: 10% on land completion, 10% on foundation, 15% on structure, etc. The developer claims each stage payment upon architect certification.' },

  // Islamic Finance
  { term: 'Musharakah Mutanaqisah (MM)', category: 'Islamic Finance', meaning: 'An Islamic home financing structure based on a diminishing partnership — the bank and customer jointly purchase the property, and the customer gradually buys out the bank\'s share through monthly instalments (comprising rent + instalment to purchase bank\'s portion).', source: 'Islamic Financial Services Act 2013; BNM Shariah standards', example: 'A customer and bank co-purchase a RM500,000 house. Customer owns 10% initially; bank owns 90%. Customer pays monthly "rental" on the bank\'s 90% plus monthly "purchase" of more bank units. Over 30 years, the customer buys out the bank\'s 90% until he owns 100%.' },
  { term: 'Bay\' Bithaman Ajil (BBA)', category: 'Islamic Finance', meaning: 'An Islamic financing structure where the bank purchases the asset and sells it to the customer at a higher price (deferred sale), payable in instalments. Now less commonly used in Malaysia.', source: 'Islamic Financial Services Act 2013; Fiqh principles', example: 'Bank buys property for RM400,000, then sells it to the customer for RM800,000 (the profit reflects the time-value of money under Islamic principles), payable over 20 years in monthly instalments of ~RM3,333.' },
  { term: 'Takaful', category: 'Islamic Finance', meaning: 'The Islamic equivalent of insurance — a cooperative scheme where participants contribute to a fund that pays claims on the occurrence of specified events. Used as an alternative to MRTA/MLTA for Islamic home financing.', source: 'Takaful Act 1984; Islamic Financial Services Act 2013', example: 'A Muslim borrower using Islamic home financing takes a Takaful Home Financing Protection Plan instead of a conventional MRTA. The fund pays out the outstanding financing amount upon death or TPD.' },

  // Compulsory Acquisition
  { term: 'Compulsory Acquisition', category: 'Compulsory Acquisition', meaning: 'The power of the Federal or State Government to compulsorily take private land for a public purpose upon payment of adequate compensation, under the Land Acquisition Act 1960.', source: 'Land Acquisition Act 1960; Federal Constitution Article 13', example: 'The government needs land for a new highway. It compulsorily acquires private land along the proposed route under the LAA 1960. The landowners receive compensation based on the market value of their land.' },
  { term: 'Market Value (in Land Acquisition)', category: 'Compulsory Acquisition', meaning: 'The price a willing buyer would pay a willing seller in an open market at the date of the acquisition declaration — the benchmark for compulsory acquisition compensation under the Land Acquisition Act 1960.', source: 'Land Acquisition Act 1960 — s.2 (definition); Cho Moi v Collector [1979]', example: 'When computing compensation for an acquired piece of agricultural land with development potential, the Collector must consider what a developer would pay for the land, not just its agricultural use value.' },
  { term: 'Collector of Land Revenue', category: 'Compulsory Acquisition', meaning: 'The state official responsible for administering land acquisition proceedings, assessing compensation, and making the acquisition Award on behalf of the State Authority.', source: 'Land Acquisition Act 1960', example: 'After the s.8 declaration gazette, the Collector holds an inquiry to hear landowner submissions and determines the compensation Award. Dissatisfied landowners may appeal to the High Court.' },
  { term: 'Injurious Affection', category: 'Compulsory Acquisition', meaning: 'Additional compensation payable to a landowner whose remaining land suffers a decrease in value as a result of the compulsory acquisition of part of their land.', source: 'Land Acquisition Act 1960 — s.14(1)(b)', example: 'A landowner\'s 5-acre plot is half-acquired for a road. The remaining 2.5 acres are now landlocked and difficult to access. The owner claims injurious affection for the reduced value of the remaining land.' },

  // Strata (Additional)
  { term: 'Sinking Fund', category: 'Strata & MC', meaning: 'A reserve fund collected from parcel owners (in addition to ordinary maintenance charges) and set aside for future capital expenditure — such as major repairs, lifts, painting, and roof replacements.', source: 'Strata Management Act 2013 — s.51', example: 'Parcel owners pay RM100/month sinking fund. After 5 years, the MC uses the accumulated RM1.2M fund to replace all the condominium\'s passenger lifts without needing to impose a special levy.' },
  { term: 'Common Property', category: 'Strata & MC', meaning: 'All parts of a strata development that are not individually owned parcels — including lobbies, corridors, swimming pools, gym, car parks (common), driveways, and the building structure.', source: 'Strata Titles Act 1985; Strata Management Act 2013', example: 'The swimming pool, lifts, and lobby are common property owned by all parcel owners collectively through the MC. No single owner can modify or sell these areas — they belong to the entire body of parcel owners.' },
  { term: 'By-Laws (Strata)', category: 'Strata & MC', meaning: 'Rules governing the use of strata parcels and common property, binding on all parcel owners, occupiers, and the MC. Includes statutory by-laws under the SMA 2013 and any additional by-laws passed at AGM.', source: 'Strata Management Act 2013 — s.70; Strata Management (Maintenance and Management) Regulations 2015 — Part 2', example: 'The statutory by-laws prohibit hanging laundry in areas visible from outside the building. The MC issues notices to owners breaching this by-law and may impose a fine or refer the matter to the Strata Management Tribunal.' },
  { term: 'Annual General Meeting (AGM) — MC/JMB', category: 'Strata & MC', meaning: 'The mandatory yearly meeting of the Management Corporation or JMB at which financial accounts are presented, committee elections are held, and decisions on major matters are taken by resolution.', source: 'Strata Management Act 2013 — s.25 (JMB); s.32 (MC)', example: 'At the annual MC AGM, parcel owners vote to approve the previous year\'s accounts, set the maintenance fee rate for the next year, and elect the five-member MC committee by show of hands.' },

  // Tenancy & Lease (Additional)
  { term: 'Diplomatic Clause', category: 'Tenancy & Lease', meaning: 'A clause in a residential tenancy agreement allowing either party to terminate the tenancy before its natural expiry by giving a specified period of notice (typically 2 months), usually where the tenant is an expatriate liable to relocation.', source: 'Tenancy Agreement — contractual clause; Contracts Act 1950', example: 'A multinational company\'s expatriate employee rents a house for 2 years with a diplomatic clause. When transferred back to headquarters at the 15-month mark, they give 2 months\' notice and terminate the tenancy without penalty.' },
  { term: 'Periodic Tenancy', category: 'Tenancy & Lease', meaning: 'A tenancy that continues for successive periods (weekly, monthly, or yearly) without a fixed end date, terminable by either party giving the appropriate notice corresponding to the rental period.', source: 'Common law; Contracts Act 1950', example: 'A tenant whose fixed-term agreement expires but who continues paying rent on a monthly basis creates a monthly periodic tenancy. Either party can terminate by giving 1 month\'s notice.' },
  { term: 'Holding Over', category: 'Tenancy & Lease', meaning: 'The continuation of a tenant\'s occupation of the rented property after the expiry of the tenancy without a new agreement, typically on the same terms as the expired agreement.', source: 'Common law; Contracts Act 1950', example: 'The tenant\'s 2-year fixed tenancy expires on 31 December but neither party does anything. The tenant continues paying rent and the landlord continues accepting it — the tenant is "holding over" on a periodic (monthly) basis.' },

  // General Conveyancing (Additional)
  { term: 'Notice to Complete', category: 'General Conveyancing', meaning: 'A formal notice issued by the innocent party (typically the vendor) to the defaulting party (typically the purchaser) requiring completion of the SPA within a reasonable specified period, after which the innocent party may rescind and forfeit the deposit.', source: 'Conveyancing practice; Ranbir Singh v Govind Singh [1995]; common law', example: 'The purchaser has not completed by the agreed date. The vendor, having already extended time once, gives a "Notice to Complete" requiring the purchaser to complete within 14 days or the SPA will be rescinded and the deposit forfeited.' },
  { term: 'Time of the Essence', category: 'General Conveyancing', meaning: 'A contractual concept where compliance with a time limit is a condition of the contract — failure to comply by the stipulated time entitles the innocent party to terminate the agreement immediately.', source: 'Contracts Act 1950; Tay Tuan Kiat v Pritam Singh Brar [1987]', example: 'An SPA states "completion shall take place on 15 October 2024, time being of the essence." If the purchaser fails to complete on that date, the vendor may immediately rescind and forfeit the deposit without any grace period.' },
  { term: 'Resulting Trust', category: 'General Conveyancing', meaning: 'A trust that arises by operation of law where a person pays the purchase price for property but the title is placed in another\'s name — the titleholder holds the property on trust for the payer proportionate to their contribution.', source: 'Equity; Au Meng Nam v Ung Yak Chew [2007]; Tan Chee Beng v Tee Peck Hoon [2003]', example: 'Ali pays RM400,000 for a piece of land but registers it in his brother\'s name to avoid attracting attention. The brother holds the land on resulting trust for Ali — despite being the registered proprietor, the brother cannot deal with it as his own.' },
  { term: 'Constructive Trust', category: 'General Conveyancing', meaning: 'A trust imposed by a court of equity to prevent unconscionable conduct — arising from a common intention between parties that one should have a beneficial interest in property, where the other has acted to their detriment in reliance on that intention.', source: 'Equity; Datuk Jagindar Singh v Tara Rajaratnam [1983]', example: 'A married couple mutually agreed the wife would have a half share in the matrimonial home, though only the husband\'s name is on the title. The wife contributed to the mortgage payments. The court imposes a constructive trust giving the wife her beneficial half share.' },
  { term: 'Specific Performance (of SPA)', category: 'General Conveyancing', meaning: 'An equitable remedy uniquely important in property law — an order directing a defaulting party to perform their obligations under the SPA, compelling the vendor to transfer the property or the purchaser to complete the purchase.', source: 'Specific Relief Act 1950 — s.11; Macon Works v Phang Hon Yin [1976]', example: 'The vendor sells the land to a higher bidder despite having signed an SPA with the original purchaser. The court orders specific performance, directing the vendor to transfer the land to the original purchaser as the contract obligates him to do.' },
  { term: 'Temporary Occupation Licence (TOL)', category: 'NLC Principles', meaning: 'A licence granted by the State Authority allowing temporary occupation and use of State Land for a specified purpose and period, without creating full alienation.', source: 'Section 65–67 NLC', example: 'A hawker stall operator on State Land holds a TOL for the land. The TOL must be renewed annually and can be revoked without compensation. It does not give the holder any ownership rights to the land.' },
  { term: 'Perpetuity Clause', category: 'Agreements', meaning: 'A clause in an SPA specifying that time is of the essence — sometimes phrased as a provision that obligations must be performed on a specific date without exception.', source: 'Contracts Act 1950; conveyancing practice', example: 'An SPA states: "It is agreed that time shall be of the essence of this agreement as regards all dates and periods mentioned herein." This confirms every deadline in the SPA is strict.' },
  { term: 'Letter of Undertaking (LOU)', category: 'Financing', meaning: 'A written promise by a solicitor (or a bank) to perform a specific act — in conveyancing, typically used between banks in refinancing or sub-sale transactions to enable simultaneous completion.', source: 'Conveyancing practice; Bar Council guidelines', example: 'In a refinancing, the new bank writes a Letter of Undertaking to the old bank: "We undertake to pay the redemption sum of RM450,000 to your account on or before [Completion Date], and upon receipt you undertake to release Form 16N and the IDT to us."' },
  { term: 'Statutory Declaration (SD)', category: 'General Conveyancing', meaning: 'A solemn written statement of facts, made under the Statutory Declarations Act 1960 before a Commissioner for Oaths. Used in conveyancing to support various applications (lost title, change of name, etc.).', source: 'Statutory Declarations Act 1960', example: 'A proprietor who has lost his original title (IDT) must make a Statutory Declaration before a Commissioner for Oaths describing the circumstances of the loss, and file it with the Land Office when applying for a replacement title.' },

  // Anti-Money Laundering
  { term: 'Customer Due Diligence (CDD)', category: 'AML Compliance', meaning: 'The process of verifying a client\'s identity, understanding the nature and purpose of the business relationship, and assessing the risk of money laundering or terrorism financing.', source: 'AMLA 2001; BNM AML/CFT Guidelines', example: 'Before acting for a purchaser, the solicitor verifies their MyKad, confirms their address, and inquires about the source of funds for the purchase. This is CDD — mandatory for all new clients.' },
  { term: 'Suspicious Transaction Report (STR)', category: 'AML Compliance', meaning: 'A confidential report filed by a reporting institution (including law firms) with Bank Negara Malaysia when a transaction appears suspicious — e.g., the client cannot explain the source of funds or structures payments to avoid reporting thresholds.', source: 'Section 14 AMLA 2001', example: 'A client insists on paying the deposit in multiple cash instalments just below RM25,000 each. The solicitor recognises this as potential "structuring" and files an STR with BNM. The client must NOT be informed.' },
  { term: 'Politically Exposed Person (PEP)', category: 'AML Compliance', meaning: 'A person who holds or has held a prominent public function (e.g., senior politician, judge, military officer), or their family members and close associates. PEPs require Enhanced Due Diligence (EDD) under AML regulations.', source: 'AMLA 2001; BNM AML/CFT Guidelines; FATF Recommendations', example: 'A state assemblyman wants to purchase a commercial property for RM3 million. The solicitor must conduct Enhanced Due Diligence — verifying source of wealth and source of funds more rigorously than for a non-PEP client.' },
  { term: 'Tipping Off', category: 'AML Compliance', meaning: 'The criminal offence of informing (directly or indirectly) a person who is the subject of a suspicious transaction report that such a report has been or is being filed. Carries imprisonment and fine.', source: 'Section 15 AMLA 2001', example: 'After filing an STR about a client\'s unusual cash payments, the solicitor must NOT tell the client "we reported your transaction." Tipping off is a criminal offence punishable by imprisonment.' },

  // Islamic Finance
  { term: 'Ibra\' (Rebate)', category: 'Islamic Finance', meaning: 'A voluntary rebate given by an Islamic bank upon early settlement of a financing facility, reducing the total amount payable to reflect the unexpired profit component. Essential in BBA and Murabahah facilities.', source: 'BNM Shariah Standards; Islamic Financial Services Act 2013', example: 'A customer with an Islamic BBA facility (total sale price RM800,000) settles early when the outstanding is RM400,000. The bank applies ibra\', reducing the amount to RM350,000 — reflecting the unearned profit component.' },
  { term: 'Ijarah (Lease-Based Financing)', category: 'Islamic Finance', meaning: 'An Islamic financing structure where the bank purchases the property and leases it to the customer. The customer pays rental and may have an option to purchase at the end of the lease period (Ijarah Thumma Al-Bay\').', source: 'Islamic Financial Services Act 2013; BNM Shariah Standards', example: 'A bank purchases a property for RM500,000 and leases it to the customer for 25 years. Monthly rental is RM2,500. At the end of 25 years, the bank transfers ownership to the customer for a nominal amount.' },
  { term: 'Wa\'d (Promise)', category: 'Islamic Finance', meaning: 'A unilateral binding promise in Islamic finance — often used in Musharakah Mutanaqisah where the bank promises to sell its share to the customer progressively, and the customer promises to buy.', source: 'BNM Shariah Standards; Islamic Banking Practice Standards', example: 'In an MM facility, the bank gives a wa\'d to sell its ownership units to the customer at an agreed price on each payment date. This promise is binding and enforceable under Malaysian law.' },

  // Developer & Construction
  { term: 'Schedule G SPA', category: 'HDA & Developer', meaning: 'The statutory Sale and Purchase Agreement prescribed under the Housing Development (Control and Licensing) Regulations 1989 for landed property (houses, bungalows, semi-detached) sold by licensed developers.', source: 'Housing Development (Control and Licensing) Regulations 1989 — Schedule G', example: 'A developer selling new double-storey terrace houses must use the Schedule G SPA. The VP delivery period is 24 months from the SPA date. LAD at 10% p.a. applies for late delivery.' },
  { term: 'Schedule H SPA', category: 'HDA & Developer', meaning: 'The statutory Sale and Purchase Agreement prescribed for stratified property (condominiums, apartments, service apartments) sold by licensed developers. Provides 36-month VP delivery period.', source: 'Housing Development (Control and Licensing) Regulations 1989 — Schedule H', example: 'A developer selling new condominium units must use the Schedule H SPA. The VP delivery period is 36 months from the SPA date. LAD at 10% p.a. applies for late delivery of vacant possession.' },
  { term: 'Housing Development Account (HDA Account)', category: 'HDA & Developer', meaning: 'A special bank account maintained by a licensed developer into which all purchaser payments must be deposited. Withdrawals are only permitted for project-related expenses and require the certifying architect\'s endorsement.', source: 'Housing Development (Control and Licensing) Act 1966 — s.7A', example: 'When a purchaser pays the 10% deposit, it goes into the developer\'s HDA Account at an approved bank. The developer can only withdraw funds from this account to pay contractors and suppliers for the specific project.' },
  { term: 'Architect\'s Certificate', category: 'HDA & Developer', meaning: 'A certificate issued by the project architect confirming a specific stage of construction has been completed, triggering the next progressive payment from the purchaser\'s financing bank.', source: 'HDA Regulations — Third Schedule', example: 'The architect certifies that the building superstructure is complete (Stage 3). The bank releases the next tranche of the loan (15% of purchase price) directly to the developer\'s HDA Account.' },

  // Land Administration
  { term: 'E-Tanah', category: 'Land Administration', meaning: 'The electronic land administration system being progressively implemented across Malaysian states, replacing manual paper-based land records with a computerised system.', source: 'NLC; State land administration directives', example: 'In states where e-Tanah is operational, title searches can be conducted online, applications for transfer can be submitted electronically, and the status of pending registrations can be tracked in real-time.' },
  { term: 'Official Search (OS)', category: 'Land Administration', meaning: 'A formal search conducted at the Land Registry or Land Office to obtain a certified extract of the land register, showing the current registered proprietor, encumbrances, endorsements, and restrictions.', source: 'NLC; conveyancing practice', example: 'Before advising a client to proceed with a purchase, the solicitor conducts an Official Search at PTG/PTD to verify the vendor\'s title, check for charges, caveats, and restrictions on the title.' },
  { term: 'Bankruptcy Search', category: 'Land Administration', meaning: 'A search conducted at the Department of Insolvency to verify whether a party to a transaction has been adjudged bankrupt. A bankrupt person cannot deal with their property without court permission.', source: 'Insolvency Act 1967; conveyancing practice', example: 'Before completion, the purchaser\'s solicitor conducts a bankruptcy search on the vendor. If the vendor is an undischarged bankrupt, the SPA may be void or voidable. The search must be current at the date of completion.' },
  { term: 'Company Search (SSM)', category: 'Land Administration', meaning: 'A search conducted at the Companies Commission of Malaysia (SSM/Suruhanjaya Syarikat Malaysia) to verify a company\'s registration status, directors, shareholders, and whether any winding-up proceedings have been commenced.', source: 'Companies Act 2016; SSM', example: 'When acting for a purchaser buying from a corporate vendor, the solicitor conducts an SSM search to confirm the company is active, identify the authorised signatories, and check for any winding-up petition.' },
  { term: 'Real Property Gains Tax Clearance', category: 'Taxation', meaning: 'The requirement for the vendor to obtain RPGT clearance from LHDN before or upon completion of a property disposal. The purchaser must retain and remit 3% of the purchase price to LHDN as withholding tax.', source: 'Real Property Gains Tax Act 1976 — s.21B', example: 'In a sub-sale at RM1,000,000, the purchaser retains RM30,000 (3%) and remits it to LHDN. The vendor files Form CKHT 1A. Once LHDN assesses the RPGT, any excess retention is refunded to the vendor.' },

  // Professional Practice
  { term: 'Completion Account', category: 'Professional Practice', meaning: 'A detailed financial statement prepared by the solicitor showing how the purchase price and all outgoings have been applied at completion — including deposits received, loan disbursements, stamp duty, legal fees, and apportionments.', source: 'Conveyancing practice; Solicitors Accounts Rules', example: 'At completion, the purchaser\'s solicitor prepares a completion account showing: purchase price RM500,000, less deposit RM50,000, less loan RM400,000 = balance from purchaser RM50,000. Adjustments for quit rent and assessment are added.' },
  { term: 'Holding Out', category: 'Professional Practice', meaning: 'The unethical practice of a solicitor holding client documents, files, or monies and refusing to release them, typically to pressure the client to pay the solicitor\'s disputed fees. This is a disciplinary offence.', source: 'Legal Profession Act 1976; Bar Council Rulings', example: 'A solicitor who has completed the conveyancing refuses to release the registered title to the client until the client pays disputed legal fees. This constitutes "holding out" and the client can report the solicitor to the Bar Council.' },
  { term: 'Conveyancing Transaction File', category: 'Professional Practice', meaning: 'The complete set of documents maintained by a solicitor for each conveyancing matter — including the SPA, title search, correspondence, completion account, receipts, and all related instruments. Must be retained for at least 6 years.', source: 'Solicitors Accounts Rules; Bar Council practice rules', example: 'A well-organised transaction file contains the SPA, title searches, bank correspondence, undertakings, stamped instruments, completion account, and client receipts — arranged chronologically with a checklist.' },

  // Electronic Conveyancing
  { term: 'e-Tanah Portal', category: 'E-Conveyancing', meaning: 'The national electronic land administration platform developed by KPTG for computerised land registration, online searches, and electronic submission of dealings.', source: 'National Land Code (Computerisation) amendments; KPTG directives', example: 'A solicitor in Selangor logs into the e-Tanah portal to conduct an official search on a Petaling Jaya property, downloads the certified search result as a PDF, and tracks the registration status of a previously presented MOT.' },
  { term: 'eTSAS', category: 'E-Conveyancing', meaning: 'Electronic Title Strata Attachment System — the digital platform for issuance and management of strata titles, integrated with e-Tanah for seamless strata land administration.', source: 'Strata Titles Act 1985; e-Tanah system', example: 'When a developer applies for strata title issuance for a completed condominium, the application is processed through eTSAS, which automatically calculates share units and generates individual strata titles.' },
  { term: 'e-Consent', category: 'E-Conveyancing', meaning: 'The electronic submission of consent applications to the State Authority for transactions requiring approval (e.g. leasehold transfers, foreign purchases), processed through e-Tanah.', source: 'NLC ss.214–215; e-Tanah system', example: 'Instead of physically submitting Form 14A with a consent application to the Land Office, the solicitor submits the application electronically via e-Consent and receives the approval notification online.' },
  { term: 'e-Carian (Electronic Search)', category: 'E-Conveyancing', meaning: 'The electronic land search service that allows practitioners to conduct official and private land searches online without physically visiting the Land Office or Registry.', source: 'NLC; e-Tanah platform', example: 'The solicitor conducts an e-Carian search at 11pm from their office, obtaining the certified search result within minutes, rather than queuing at the Land Office the next morning.' },
  { term: 'e-Stamp (STAMPS)', category: 'E-Conveyancing', meaning: 'The electronic stamping system (Sistem Taksiran dan Pembayaran Setem — STAMPS) operated by LHDN for online assessment and payment of stamp duty on instruments.', source: 'Stamp Act 1949; LHDN directives', example: 'After executing the SPA, the solicitor uploads the instrument details to STAMPS, pays the stamp duty online, and downloads the e-Stamp certificate. The instrument is now properly stamped without visiting the LHDN office.' },
  { term: 'Digital Signature (Land)', category: 'E-Conveyancing', meaning: 'An electronic signature recognised under the NLC amendments for computerised land registration, having the same legal effect as a wet-ink signature on land instruments.', source: 'NLC s.5A; Digital Signature Act 1997', example: 'In states with full e-Tanah implementation, the Registrar applies a digital signature to confirm registration of a transfer, replacing the traditional stamp and signature on the physical IDT.' },
  { term: 'MyTanah', category: 'E-Conveyancing', meaning: 'The public-facing online portal for landowners to check their land title information, verify ownership status, and track pending applications without engaging a solicitor.', source: 'KPTG; e-Tanah initiative', example: 'A property owner logs into MyTanah to verify their title details before meeting a solicitor to sell their property, ensuring the information matches their IDT.' },

  // Land Acquisition
  { term: 'Section 4 Notice (LAA)', category: 'Land Acquisition', meaning: 'A preliminary notice published in the Gazette under s.4 of the Land Acquisition Act 1960, indicating that a particular piece of land is likely needed for a public purpose and authorising entry for investigation.', source: 'Land Acquisition Act 1960 — s.4', example: 'The State Government publishes a s.4 notice for a parcel in Sepang needed for a new highway. This alerts the owner that acquisition is being considered, but does not yet constitute acquisition.' },
  { term: 'Section 8 Declaration (LAA)', category: 'Land Acquisition', meaning: 'A formal declaration published in the Gazette under s.8 LAA that the specified land is needed for acquisition. Once published, the land is effectively marked for acquisition and further dealings are restricted.', source: 'Land Acquisition Act 1960 — s.8', example: 'After the s.4 investigation, the State publishes a s.8 declaration for the highway route. From this date, the landowner cannot transfer, charge, or further develop the land. The compensation quantum is assessed based on the market value at this date.' },
  { term: 'Solatium', category: 'Land Acquisition', meaning: 'An additional payment of 10% (residential) or 20% (non-residential) above the market value awarded to the landowner as compensation for the compulsory nature of the acquisition.', source: 'Land Acquisition Act 1960 — First Schedule', example: 'The Land Administrator awards RM1,000,000 as market value for a residential lot. An additional RM100,000 (10%) solatium is added, making the total compensation RM1,100,000.' },
  { term: 'Section 37 Reference (LAA)', category: 'Land Acquisition', meaning: 'An application to the High Court by any party dissatisfied with the Land Administrator\'s compensation award, seeking judicial reassessment of the compensation amount.', source: 'Land Acquisition Act 1960 — s.37', example: 'The landowner believes the RM1.1 million award undervalues the property. They file a s.37 reference to the High Court, where a judge reassesses the evidence and awards RM1.8 million based on comparable sales data.' },
  { term: 'Eminent Domain', category: 'Land Acquisition', meaning: 'The sovereign right of the State to compulsorily acquire private land for public purposes, subject to the payment of adequate compensation. Known as "kuasa pengambilan" in Malay.', source: 'Federal Constitution Art. 13; Land Acquisition Act 1960', example: 'The State invokes its power of eminent domain to acquire a row of shophouses for a new MRT station. The shophouse owners cannot refuse but are entitled to fair compensation.' },
  { term: 'Severance Damage', category: 'Land Acquisition', meaning: 'The diminution in value of the landowner\'s remaining land caused by the compulsory acquisition of only part of their larger holding.', source: 'Land Acquisition Act 1960 — First Schedule', example: 'The State acquires the front portion of a large agricultural estate for a road. The remaining back portion loses access and its value drops significantly. The owner claims severance damage in addition to the value of the acquired portion.' },

  // AML/CFT
  { term: 'Customer Due Diligence (CDD)', category: 'AML/CFT', meaning: 'The process of verifying a client\'s identity, understanding the nature of their business relationship, and assessing money laundering risk before accepting them as a client.', source: 'AMLA 2001 (Act 613); BNM Guidelines on AML/CFT', example: 'Before acting for a purchaser, the solicitor collects a certified copy of the MyKad, verifies the person matches the photo, obtains proof of address, and records the source of funds for the purchase.' },
  { term: 'Enhanced Due Diligence (EDD)', category: 'AML/CFT', meaning: 'Additional verification measures required for high-risk clients, including Politically Exposed Persons (PEPs), high-value cash transactions, and complex corporate structures.', source: 'AMLA 2001; BNM Guidelines', example: 'A client purchasing property through a BVI company triggers EDD requirements. The solicitor must verify the beneficial owner behind the corporate chain, source of wealth, and purpose of the structure.' },
  { term: 'Suspicious Transaction Report (STR)', category: 'AML/CFT', meaning: 'A mandatory report filed with Bank Negara Malaysia when a solicitor has reasonable grounds to suspect that a transaction involves proceeds of unlawful activity or terrorism financing.', source: 'AMLA 2001 — s.14', example: 'A client wants to pay RM2 million in cash for a property with no credible explanation of the source. The solicitor files an STR with BNM and continues acting (to avoid tipping off) unless BNM directs otherwise.' },
  { term: 'Tipping Off', category: 'AML/CFT', meaning: 'The criminal offence of disclosing to a client or any other person that an STR has been or will be filed, or that a money laundering investigation is being or may be conducted.', source: 'AMLA 2001 — s.15', example: 'After filing an STR, the solicitor must not tell the client "I have reported you to BNM." Doing so is a criminal offence punishable by fine and imprisonment.' },
  { term: 'Politically Exposed Person (PEP)', category: 'AML/CFT', meaning: 'An individual who holds or has held a prominent public position (e.g. minister, senior government official, judge, military officer) and is therefore subject to enhanced due diligence in financial transactions.', source: 'AMLA 2001; BNM Guidelines on AML/CFT', example: 'A retired State Minister wishes to purchase commercial property. Even though retired, the solicitor classifies them as a PEP and conducts enhanced due diligence including verification of source of wealth.' },
  { term: 'Beneficial Owner', category: 'AML/CFT', meaning: 'The natural person who ultimately owns or controls a legal entity or arrangement, or on whose behalf a transaction is being conducted, regardless of who the registered owner is.', source: 'AMLA 2001; Companies Act 2016 s.60', example: 'Property is registered in the name of ABC Sdn Bhd. CDD reveals that the company is 100% owned by a BVI holding company, which is ultimately controlled by one individual — that individual is the beneficial owner.' },
  { term: 'Cash Threshold Report (CTR)', category: 'AML/CFT', meaning: 'A mandatory report for cash transactions exceeding RM25,000 (or its equivalent) that must be filed with BNM, regardless of whether the transaction appears suspicious.', source: 'AMLA 2001; BNM AML/CFT Reporting Guidelines', example: 'A purchaser pays the 10% deposit of RM100,000 in cash. The solicitor must file a CTR with BNM and also consider whether the circumstances warrant an STR.' },

  // Wills & Succession
  { term: 'Grant of Probate', category: 'Wills & Succession', meaning: 'A court order issued to the executor named in a valid will, authorising them to administer the deceased\'s estate, including dealing with land assets.', source: 'Probate and Administration Act 1959', example: 'The deceased\'s will names Ali as executor. Ali applies to the High Court and obtains a Grant of Probate, which he then presents to the Land Office to register himself as the personal representative on the land title.' },
  { term: 'Letters of Administration', category: 'Wills & Succession', meaning: 'A court order issued to an administrator when a person dies intestate (without a will) or when the named executor cannot or will not act, authorising the administrator to manage the estate.', source: 'Probate and Administration Act 1959', example: 'Encik Ahmad dies without a will. His wife applies to the High Court for Letters of Administration and, once granted, can proceed to transfer the house to herself and the children per the Distribution Act 1958.' },
  { term: 'Faraid', category: 'Wills & Succession', meaning: 'The Islamic law of inheritance that prescribes fixed shares for each category of heirs (e.g. spouse, children, parents). Applies to Muslim estates and takes precedence over the Distribution Act.', source: 'Quran and Sunnah; Syariah Court jurisdiction', example: 'A Muslim property owner dies leaving a wife, 2 sons and 1 daughter. Under faraid, the wife receives 1/8, and the remainder is shared among the children with each son receiving double the daughter\'s share.' },
  { term: 'Wasiyyah', category: 'Wills & Succession', meaning: 'An Islamic testamentary bequest that allows a Muslim to dispose of up to 1/3 of their estate by will. The remaining 2/3 must be distributed according to faraid.', source: 'Islamic law; Syariah Court rules', example: 'Puan Aminah executes a wasiyyah bequeathing 1/3 of her estate to a charitable waqf. The remaining 2/3 of her estate, including her house, is distributed among her faraid heirs.' },
  { term: 'Right of Survivorship', category: 'Wills & Succession', meaning: 'The principle that when land is held by joint tenants (berkelompok), upon the death of one joint tenant, the entire interest automatically vests in the surviving joint tenant(s) by operation of law.', source: 'NLC; Latifah bte Mat Zin v Rosmawati bte Sharibun [2007] 5 MLJ 101', example: 'Husband and wife hold their house as joint tenants. When the husband dies, the wife automatically becomes sole proprietor by right of survivorship — no probate or letters of administration is needed for the house.' },
  { term: 'Small Estate', category: 'Wills & Succession', meaning: 'An estate with a total value not exceeding RM2 million, which can be administered by the District Land Administrator through a simplified and faster process instead of the High Court.', source: 'Small Estates (Distribution) Act 1955', example: 'A father dies leaving a house worth RM800,000 and savings of RM200,000 (total RM1 million). The family applies to the District Land Administrator instead of the High Court, saving time and legal fees.' },
  { term: 'Form 14B (Personal Representative)', category: 'Wills & Succession', meaning: 'The NLC form used by an executor or administrator to register themselves as the proprietor of land belonging to the deceased, as the first step in transmission upon death.', source: 'NLC s.327; Form 14B', example: 'The executor presents the Grant of Probate and Form 14B to the Land Office. Once registered, the executor\'s name appears on the title as "personal representative of [deceased]" and can then transfer the land to beneficiaries.' },

  // East Malaysia
  { term: 'Country Lease (Sabah)', category: 'East Malaysia', meaning: 'The form of land title in Sabah equivalent to a grant or freehold title in Peninsular Malaysia, issued under the Sabah Land Ordinance for rural or agricultural land.', source: 'Sabah Land Ordinance (Cap. 68)', example: 'A rubber plantation in Sandakan holds a Country Lease (CL) title. When the owner wishes to sell, the transfer instrument follows the Sabah Land Ordinance procedures, not the NLC.' },
  { term: 'Town Lease (Sabah)', category: 'East Malaysia', meaning: 'A leasehold title issued for urban land in Sabah, typically for 99 or 999 years, governed by the Sabah Land Ordinance.', source: 'Sabah Land Ordinance (Cap. 68)', example: 'A shophouse in Kota Kinabalu holds a Town Lease for 999 years. Despite the long tenure, it remains technically leasehold and is subject to conditions set by the state government.' },
  { term: 'Native Title (NT) — Sabah', category: 'East Malaysia', meaning: 'A special form of title in Sabah that can only be held by a native of Sabah (as defined in the Federal Constitution), recognising customary land rights.', source: 'Sabah Land Ordinance (Cap. 68); Federal Constitution', example: 'A Kadazan farmer holds Native Title land in Kota Belud. The land cannot be transferred to a non-native without conversion of the title, which requires state consent and may be refused.' },
  { term: 'Native Customary Rights (NCR) — Sarawak', category: 'East Malaysia', meaning: 'Rights over land established by natives of Sarawak through occupation and cultivation of virgin jungle before 1 January 1958, recognised by law as proprietary rights.', source: 'Sarawak Land Code (Cap. 81); Nor Anak Nyawai v Borneo Pulp [2001]', example: 'An Iban community has cultivated a section of jungle land in Kapit since the 1940s. They have NCR over this land even without a formal title and can apply under s.18 of the Land Code for formalisation.' },
  { term: 'Mixed Zone Land (Sarawak)', category: 'East Malaysia', meaning: 'A category of land in Sarawak that can be held by any person regardless of race or native status, as opposed to Native Area Land which is restricted.', source: 'Sarawak Land Code (Cap. 81)', example: 'A Chinese businessman purchases a commercial lot in Kuching classified as Mixed Zone Land. No native status requirement applies, unlike Native Area Land which is restricted to Sarawak natives.' },
  { term: 'Interior Area Land (Sarawak)', category: 'East Malaysia', meaning: 'Land in the interior of Sarawak that is largely undeveloped and may be subject to native customary rights. Government consent is required for dealings.', source: 'Sarawak Land Code (Cap. 81)', example: 'A logging company wishes to operate on Interior Area Land in the upper Rajang. It must obtain a licence from the Superintendent of Lands and verify that no NCR claims exist over the area.' },

  // Environmental & Planning
  { term: 'Environmental Impact Assessment (EIA)', category: 'Environmental & Planning', meaning: 'A mandatory study required before commencement of prescribed development activities (e.g. housing estates > 50 hectares), assessing the environmental impact and proposing mitigation measures.', source: 'Environmental Quality Act 1974 — s.34A; EQ (Prescribed Activities) Order 2015', example: 'A developer planning 800 units on 60 hectares must commission a registered EIA consultant to prepare an EIA report and submit it to DOE for approval before applying for building plans.' },
  { term: 'Certificate of Completion and Compliance (CCC)', category: 'Environmental & Planning', meaning: 'A certificate issued by the Principal Submitting Person (architect/engineer) confirming that a building has been completed in accordance with approved plans and building by-laws. Replaced CFO in 2007.', source: 'Street, Drainage and Building Act 1974; Uniform Building By-Laws 1984', example: 'Upon completion of a condominium tower, the architect issues the CCC. This triggers the developer\'s obligation to deliver vacant possession to purchasers within 14 days.' },
  { term: 'Development Order (Kebenaran Merancang)', category: 'Environmental & Planning', meaning: 'An order issued by the Local Planning Authority granting planning permission for proposed development, after considering conformity with the local plan, environmental impact, and other factors.', source: 'Town and Country Planning Act 1976 — s.22', example: 'A developer receives a Development Order from MBPJ authorising construction of 200 terrace houses on agricultural land in Subang. The order specifies conditions including road widening, open space provision, and drainage requirements.' },
  { term: 'Conversion Premium', category: 'Environmental & Planning', meaning: 'A payment to the State Authority for changing the category of land use (e.g. from agriculture to building) or for lifting restrictions, calculated based on the enhanced value of the land.', source: 'NLC ss.124, 124A', example: 'A developer converts 10 acres of rubber estate (agriculture category) to "building" category for a housing project. The State charges a conversion premium of RM2 million based on the increase in land value from the change.' },
  { term: 'Earthworks Approval', category: 'Environmental & Planning', meaning: 'Approval required under the Street, Drainage and Building Act 1974 before any earth-moving, land-clearing, or grading work can commence on a development site.', source: 'Street, Drainage and Building Act 1974 (Act 133)', example: 'Before clearing the hillside site, the developer must submit an earthworks plan with an Erosion and Sediment Control Plan (ESCP) to the local authority for approval. Commencing earthworks without approval is a criminal offence.' },
  { term: 'Environmentally Sensitive Area (ESA)', category: 'Environmental & Planning', meaning: 'An area designated as environmentally sensitive and classified into ranks: Rank 1 (no development), Rank 2 (restricted development), Rank 3 (controlled development).', source: 'National Physical Plan; State structure plans', example: 'A parcel in Cameron Highlands is classified as ESA Rank 2. The developer must obtain DOE approval and comply with strict conditions including maintaining 30% green buffer zones and limiting building height.' },
  { term: 'Local Plan (Rancangan Tempatan)', category: 'Environmental & Planning', meaning: 'A statutory plan prepared by the Local Planning Authority setting out detailed land use zoning, density, building height, and development guidelines for a specific area.', source: 'Town and Country Planning Act 1976 — s.12', example: 'The Rancangan Tempatan for Petaling Jaya zones a particular area as "residential — medium density" with maximum 40 units per acre and 4-storey height limit. Any development must conform to these parameters.' },

  // Developer & Housing
  { term: 'Housing Developer Licence', category: 'Developer & Housing', meaning: 'A licence issued by the Controller of Housing under the HDA 1966 that must be obtained by any person carrying on the business of housing development, before selling or advertising any unit.', source: 'Housing Development (Control & Licensing) Act 1966 — s.3', example: 'Before launching sales for a new condominium project, the developer applies to KPKT for a Housing Developer Licence and an Advertisement Permit. Selling without a licence is a criminal offence carrying up to 3 years\' imprisonment.' },
  { term: 'Housing Development Account (HDA)', category: 'Developer & Housing', meaning: 'A designated bank account that every licensed developer must maintain for each project, into which all purchaser instalments are deposited. Withdrawals require architect certification of construction progress.', source: 'Housing Development (Control & Licensing) Act 1966 — Reg. 7', example: 'Purchasers\' progressive payments are deposited into the project\'s HDA. The developer can only withdraw funds when the architect certifies that, for example, the superstructure of Floor 5 is complete (Stage 2D).' },
  { term: 'Liquidated Ascertained Damages (LAD)', category: 'Developer & Housing', meaning: 'Pre-agreed damages payable by the developer to the purchaser for late delivery of vacant possession, calculated at 10% per annum on the purchase price from the due date to the actual VP date.', source: 'HDA 1966 — Schedule G (Clause 26), Schedule H (Clause 27)', example: 'The SPA requires VP within 36 months (by 1 Jan 2025). VP is delivered on 1 Jul 2025 — 6 months late. LAD = 10% × RM500,000 × (6/12) = RM25,000 payable by the developer to the purchaser.' },
  { term: 'Defect Liability Period (DLP)', category: 'Developer & Housing', meaning: 'The 24-month period commencing from the date of vacant possession during which the developer is obligated to repair, at the developer\'s cost, any defects in the property reported by the purchaser.', source: 'HDA 1966 — Schedule G (Clause 27), Schedule H (Clause 28)', example: 'The purchaser receives VP on 1 March 2025. During the DLP (until 28 Feb 2027), the purchaser discovers ceiling leaks and cracked tiles. The developer must repair these defects at its own cost.' },
  { term: 'Tribunal for Homebuyer Claims', category: 'Developer & Housing', meaning: 'A specialised tribunal established under the HDA 1966 to hear claims by homebuyers against developers for amounts not exceeding RM50,000, with simplified procedures and no legal representation.', source: 'HDA 1966 — Part VI', example: 'A homebuyer claims RM30,000 for unrectified defects during the DLP. They file at the Tribunal (filing fee RM10), appear without a lawyer, and receive a decision within 60 days.' },

  // Legal Fees & Costs
  { term: 'Solicitors Remuneration Order (SRO)', category: 'Legal Fees', meaning: 'The statutory instrument prescribing the scale of legal fees that solicitors may charge for conveyancing and related work. The current version is SRO 2023.', source: 'Legal Profession Act 1976 — s.113; Solicitors Remuneration Order 2023', example: 'For a RM1 million property purchase, the SRO 2023 scale fee is: 1% on first RM500K = RM5,000 + 0.8% on next RM500K = RM4,000. Total = RM9,000 (plus 8% SST and disbursements).' },
  { term: 'Taxation of Bills', category: 'Legal Fees', meaning: 'The process of having a solicitor\'s bill reviewed by a court taxing officer, available to clients who believe they have been overcharged. Must be applied for within 12 months of payment.', source: 'Legal Profession Act 1976 — s.120', example: 'A client believes the solicitor charged RM25,000 when the SRO scale allows only RM15,000. The client applies for taxation of the bill at the High Court, and the taxing master reduces the bill to RM15,000.' },
  { term: 'Service Tax (SST) on Legal Fees', category: 'Legal Fees', meaning: 'An 8% service tax imposed on professional fees charged by law firms registered under the Service Tax Act 2018. SST applies to legal fees but not to disbursements.', source: 'Service Tax Act 2018; Service Tax Regulations 2018', example: 'Legal fees for an SPA are RM10,000. SST at 8% = RM800. Disbursements (searches, stamp duty) are RM2,500. Total bill = RM10,000 + RM800 + RM2,500 = RM13,300.' },
  { term: 'Touting', category: 'Legal Fees', meaning: 'The prohibited practice of soliciting conveyancing work through agents, referral fees, kickbacks to estate agents or bank officers, or any form of commission-based referrals.', source: 'Legal Profession (Practice & Etiquette) Rules 1978 — Rule 53; Bar Council Rulings', example: 'A solicitor pays a property agent RM500 for every client referred. This is touting — a serious disciplinary offence that can result in suspension or striking off the Roll.' },

  // Dispute Resolution
  { term: 'Specific Performance', category: 'Dispute Resolution', meaning: 'An equitable court remedy ordering the defaulting party to carry out their obligations under the SPA — typically ordering completion of the sale and transfer of the property.', source: 'Specific Relief Act 1950 — s.11; Macon Works v Phang Hon Yin [1976]', example: 'The vendor refuses to complete the sale after signing the SPA. The purchaser sues for specific performance. The court orders the vendor to execute the MOT and complete the transaction.' },
  { term: 'Lis Pendens Caveat', category: 'Dispute Resolution', meaning: 'A caveat lodged against a land title to give notice that court proceedings involving the land are pending. Prevents the defendant from disposing of the property during litigation.', source: 'NLC s.320; Rules of Court 2012', example: 'A purchaser sues the vendor for specific performance and simultaneously lodges a lis pendens caveat on the title. This prevents the vendor from selling to a third party while the case is pending.' },
  { term: 'Mareva Injunction (Freezing Order)', category: 'Dispute Resolution', meaning: 'A court order freezing the defendant\'s assets (including land) to prevent dissipation pending resolution of the dispute. Named after the English case Mareva Compania Naviera SA.', source: 'Courts of Judicature Act 1964 — s.25(2); Rules of Court 2012', example: 'A defrauded purchaser discovers the vendor is transferring other assets. The court grants a Mareva injunction freezing all the vendor\'s properties and bank accounts pending trial.' },
  { term: 'Rescission of Contract', category: 'Dispute Resolution', meaning: 'The unwinding of the SPA, restoring both parties to their pre-contract position. Available for fundamental breach, misrepresentation, or mutual agreement.', source: 'Contracts Act 1950 — s.66; Relief Act 1950', example: 'The purchaser discovers the vendor does not actually own the property (fundamental breach). The court orders rescission: the deposit is returned to the purchaser and the SPA is treated as if it never existed.' },
  { term: 'Anton Piller Order', category: 'Dispute Resolution', meaning: 'A court order (now called a "search order") allowing a party to enter the opposing party\'s premises and seize evidence to prevent its destruction, relevant in fraud cases.', source: 'Rules of Court 2012; inherent jurisdiction of the High Court', example: 'In a syndicated property fraud case, the plaintiff obtains an Anton Piller order to enter the defendant developer\'s office and seize forged title documents before they can be destroyed.' },
  { term: 'Limitation Period', category: 'Dispute Resolution', meaning: 'The statutory time limit within which a legal action must be commenced — 6 years for contract claims, 12 years for land recovery actions.', source: 'Limitation Act 1953 — s.6 (contract), s.9 (land)', example: 'A vendor breaches the SPA in January 2020. The purchaser must commence a court action by January 2026 (6 years). After that, the claim is time-barred.' },

  // Financing & Banking
  { term: 'Letter of Offer (LO)', category: 'Financing & Banking', meaning: 'A formal letter from the bank to the borrower specifying the terms and conditions of the housing loan — interest rate, tenure, monthly instalment, and conditions precedent to disbursement.', source: 'Banking and Financial Institutions Act 1989; banking practice', example: 'After credit approval, Maybank issues a Letter of Offer to the purchaser for a RM800,000 loan at 4.2% p.a. for 35 years. The purchaser has 14 days to accept and return the signed LO.' },
  { term: 'Facility Agreement (Loan Agreement)', category: 'Financing & Banking', meaning: 'The comprehensive legal document governing the housing loan, executed between the bank (financier) and borrower, setting out all terms, conditions, covenants, and events of default.', source: 'Banking practice; NLC (charge provisions)', example: 'The purchaser\'s solicitor prepares the Facility Agreement incorporating the LO terms. It is executed by the borrower, stamped at LHDN (0.5% of loan amount), and the original is kept by the bank.' },
  { term: 'Charge (Gadaian)', category: 'Financing & Banking', meaning: 'A statutory security interest registered on the land title under the NLC (Form 16A) in favour of a chargee (lender), giving the lender the right to sell the land if the borrower defaults.', source: 'NLC — Part Sixteen (ss.241–280)', example: 'The bank registers a charge on the purchaser\'s title using Form 16A. If the borrower defaults on the loan, the bank can exercise its power of sale under the charge to recover the outstanding amount.' },
  { term: 'Deed of Assignment (DOA)', category: 'Financing & Banking', meaning: 'A document assigning the purchaser\'s rights and interest in the property (under the SPA) to the bank as security, used when individual title has not yet been issued.', source: 'Contracts Act 1950; banking practice', example: 'For a new condominium without strata title, the bank takes a Deed of Assignment over the purchaser\'s rights under the SPA. Once strata title is issued, the bank registers a formal charge to replace the DOA.' },
  { term: 'Redemption Statement', category: 'Financing & Banking', meaning: 'A statement from the bank showing the total outstanding amount needed to fully discharge the loan and release the charge on the property.', source: 'Banking practice; conveyancing practice', example: 'Before completion of a sub-sale, the vendor\'s solicitor requests a redemption statement from CIMB Bank. The statement shows: outstanding principal RM350,000 + accrued interest RM1,200 + early settlement fee RM500 = RM351,700.' },
  { term: 'Discharge of Charge (Form 16N)', category: 'Financing & Banking', meaning: 'The NLC form used to cancel a registered charge on the land title once the loan has been fully repaid. Must be signed by the chargee (bank) and presented at the Land Office.', source: 'NLC — s.281; Form 16N', example: 'After full settlement, the bank signs Form 16N and returns it with the original IDT to the borrower\'s solicitor, who presents both to the Land Office for registration of the discharge.' },
  { term: 'Power of Attorney (PA)', category: 'Financing & Banking', meaning: 'A legal instrument authorising one person (the attorney) to act on behalf of another (the donor) in specified matters. In conveyancing, commonly used when the proprietor is overseas.', source: 'Powers of Attorney Act 1949; NLC s.310', example: 'An owner living in Australia executes a Power of Attorney in favour of their Malaysian solicitor to sign the SPA, MOT, and all related documents. The PA must be notarised and apostilled.' },
  { term: 'Bridging Loan', category: 'Financing & Banking', meaning: 'A short-term loan to finance a property purchase before the purchaser\'s existing property is sold or the main loan is approved, "bridging" the gap between purchase and sale.', source: 'Banking practice', example: 'A couple buys a new house for RM1.2 million but hasn\'t sold their old house. They take a bridging loan to fund the purchase. Once the old house is sold, the proceeds repay the bridging loan.' },

  // Islamic Finance
  { term: 'Bay\' Bithaman Ajil (BBA)', category: 'Islamic Finance', meaning: 'An Islamic financing product where the bank purchases the property and sells it to the customer at a marked-up price payable in instalments, avoiding interest (riba).', source: 'Islamic Financial Services Act 2013; BNM Shariah guidelines', example: 'Instead of an interest-based loan, Bank Islam uses BBA: the bank buys the property at RM500,000 and sells it to the customer at RM750,000 payable over 30 years in monthly instalments of RM2,083.' },
  { term: 'Musharakah Mutanaqisah (MM)', category: 'Islamic Finance', meaning: 'A diminishing partnership Islamic financing where the bank and customer jointly own the property, and the customer gradually buys the bank\'s share through periodic payments until full ownership.', source: 'Islamic Financial Services Act 2013; BNM guidelines', example: 'Under an MM arrangement, the bank owns 80% and the customer 20% of a RM1 million property. The customer pays monthly "rent" on the bank\'s share and gradually acquires the bank\'s portion over 30 years.' },
  { term: 'Takaful', category: 'Islamic Finance', meaning: 'Islamic insurance based on mutual cooperation (ta\'awun) and donation (tabarru\'), used as an alternative to conventional insurance in property financing and protection.', source: 'Islamic Financial Services Act 2013; Takaful Act 1984', example: 'A purchaser with an Islamic home financing takes a Mortgage Reducing Term Takaful (MRTT) plan instead of MRTA, ensuring the outstanding financing is covered in case of death or total disability.' },
];

const CATEGORIES = Array.from(new Set(TERMS.map(t => t.category))).sort();

function TermCard({ term, index }: { term: Term; index: number }) {
  const [open, setOpen] = useState(false);
  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: Math.min(index * 0.03, 0.4) }}
      className="bg-gold-900 border border-gold-800 rounded-xl overflow-hidden"
    >
      <button
        data-testid={`term-toggle-${term.term.replace(/\s+/g, '-').toLowerCase()}`}
        onClick={() => setOpen(v => !v)}
        className="w-full flex items-center justify-between p-4 md:p-5 text-left hover:bg-gold-800/50 transition-colors group"
      >
        <div className="flex-1 min-w-0 pr-4">
          <div className="flex items-center gap-2 flex-wrap">
            <h3 className="font-serif font-bold text-slate-100 text-base group-hover:text-amber-400 transition-colors">{term.term}</h3>
            <span className="text-xs font-mono text-amber-500/70 bg-amber-500/10 px-2 py-0.5 rounded-full shrink-0">{term.category}</span>
          </div>
          {!open && (
            <p className="text-sm text-slate-400 mt-1 line-clamp-1">{term.meaning}</p>
          )}
        </div>
        {open ? <ChevronUp className="w-4 h-4 text-slate-400 shrink-0" /> : <ChevronDown className="w-4 h-4 text-slate-400 shrink-0" />}
      </button>

      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            initial={{ height: 0 }}
            animate={{ height: 'auto' }}
            exit={{ height: 0 }}
            className="overflow-hidden"
          >
            <div className="px-4 pb-5 md:px-5 space-y-4 border-t border-gold-800">
              <div className="pt-4">
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Meaning</p>
                <p className="text-sm text-slate-300 leading-relaxed">{term.meaning}</p>
              </div>
              <div>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Legal Source</p>
                <p className="text-sm text-amber-400 font-mono bg-amber-500/5 border border-amber-500/20 rounded-lg px-3 py-2">{term.source}</p>
              </div>
              <div>
                <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-1.5">Example in Practice</p>
                <p className="text-sm text-slate-300 leading-relaxed bg-gold-800/60 rounded-lg px-3 py-3 border border-gold-700">{term.example}</p>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export function TerminologySection() {
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return TERMS.filter(t => {
      const matchesSearch = !q || t.term.toLowerCase().includes(q) || t.meaning.toLowerCase().includes(q) || t.source.toLowerCase().includes(q) || t.example.toLowerCase().includes(q);
      const matchesCat = !activeCategory || t.category === activeCategory;
      return matchesSearch && matchesCat;
    });
  }, [search, activeCategory]);

  return (
    <div className="max-w-3xl mx-auto pb-20">
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-3">
          <div className="p-2 bg-amber-500/10 rounded-lg">
            <BookMarked className="w-6 h-6 text-amber-500" />
          </div>
          <h1 className="text-3xl font-serif font-bold text-slate-100">Legal Terminology</h1>
        </div>
        <p className="text-slate-400 text-sm leading-relaxed">
          {TERMS.length} essential Malaysian conveyancing terms — each with its precise legal meaning, statutory source, and a practical worked example.
        </p>
      </div>

      {/* Search */}
      <div className="relative mb-5">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 pointer-events-none" />
        <input
          data-testid="input-term-search"
          type="text"
          placeholder="Search terms, meanings, or legal sources..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="w-full bg-gold-900 border border-gold-700 rounded-xl pl-11 pr-4 py-3.5 text-slate-100 text-sm focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 placeholder:text-slate-500"
        />
        {search && (
          <button onClick={() => setSearch('')} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 hover:text-slate-300 text-xs font-medium">
            Clear
          </button>
        )}
      </div>

      {/* Category Filter */}
      <div className="flex flex-wrap gap-2 mb-7">
        <button
          data-testid="filter-all"
          onClick={() => setActiveCategory(null)}
          className={`text-xs font-bold px-3 py-1.5 rounded-full border transition-all ${!activeCategory ? 'bg-amber-500/10 border-amber-500/40 text-amber-400' : 'bg-gold-900 border-gold-700 text-slate-400 hover:border-slate-600'}`}
        >
          All ({TERMS.length})
        </button>
        {CATEGORIES.map(cat => {
          const count = TERMS.filter(t => t.category === cat).length;
          return (
            <button
              key={cat}
              data-testid={`filter-${cat.replace(/\s+/g, '-').toLowerCase()}`}
              onClick={() => setActiveCategory(cat === activeCategory ? null : cat)}
              className={`text-xs font-bold px-3 py-1.5 rounded-full border transition-all ${activeCategory === cat ? 'bg-amber-500/10 border-amber-500/40 text-amber-400' : 'bg-gold-900 border-gold-700 text-slate-400 hover:border-slate-600'}`}
            >
              {cat} ({count})
            </button>
          );
        })}
      </div>

      {/* Results count */}
      {(search || activeCategory) && (
        <p className="text-xs text-slate-500 mb-4">
          Showing {filtered.length} of {TERMS.length} terms
        </p>
      )}

      {/* Terms List */}
      {filtered.length > 0 ? (
        <div className="space-y-3">
          {filtered.map((term, i) => <TermCard key={term.term} term={term} index={i} />)}
        </div>
      ) : (
        <div className="text-center py-16 text-slate-500">
          <BookMarked className="w-10 h-10 mx-auto mb-3 opacity-30" />
          <p className="font-medium">No terms found for "{search}"</p>
          <p className="text-sm mt-1">Try a different search term or clear the filter.</p>
        </div>
      )}
    </div>
  );
}
